=== FILE: rr_arbiter.v ===
`timescale 1ns / 1ps
// ---------------------------------------------------------------------------
// rr_arbiter: round-robin arbiter for N requesters (default N = 4).
//
// Implements microarchitecture.md (rr_arbiter) for interface_spec.md.
//   State  : ptr, $clog2(N) bits, the index of the highest-priority requester.
//            Reset synchronously to 0 by active-low rst_n.
//   Grant  : combinational wrapping priority search starting at ptr. The wrap
//            compares against N-1 explicitly, so an N that is not a power of
//            two works. grant is one-hot or zero and only to a requester.
//   Update : on a rising edge with a grant, ptr <= winner + 1, wrapping from
//            N-1 to 0. With no request, ptr holds. grant is not gated by reset.
// ---------------------------------------------------------------------------
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer PW = $clog2(N);

    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_nxt;
    reg           found;
    integer       winner;
    integer       idx;
    wire [31:0]   ptr_ext;

    integer k;
    integer i;

    assign ptr_ext = {{(32 - PW){1'b0}}, ptr};

    // Wrapping priority search: walk from ptr upwards, wrap after N-1.
    always @* begin
        found  = 1'b0;
        winner = 0;
        idx    = ptr_ext;
        for (k = 0; k < N; k = k + 1) begin
            if (!found && req[idx]) begin
                found  = 1'b1;
                winner = idx;
            end
            if (idx == N - 1) idx = 0;
            else              idx = idx + 1;
        end
    end

    // Grant vector and next pointer (one past the winner, wrapping at N).
    always @* begin
        grant   = {N{1'b0}};
        ptr_nxt = ptr;
        for (i = 0; i < N; i = i + 1) begin
            if (found && (winner == i)) begin
                grant[i] = 1'b1;
                if (i == N - 1) ptr_nxt = {PW{1'b0}};
                else            ptr_nxt = i[PW-1:0] + 1;
            end
        end
    end

    // Pointer register: reset value and load only.
    always @(posedge clk) begin
        if (!rst_n) ptr <= {PW{1'b0}};
        else        ptr <= ptr_nxt;
    end

`ifdef FORMAL
    // Design-intent properties (microarchitecture.md section 5).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    wire [31:0] f_dist_win = (winner >= ptr_ext) ? (winner - ptr_ext)
                                                  : (winner + N - ptr_ext);

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
        if (f_past_valid) begin
            assert (ptr_ext < N);
            assert ((grant & (grant - 1'b1)) == {N{1'b0}});
            assert ((grant & ~req) == {N{1'b0}});
            if (req != {N{1'b0}}) assert (grant != {N{1'b0}});
            if (found) assert (winner < N);
            cover (rst_n && (&req));
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert (ptr == {PW{1'b0}});
            else if ($past(found))
                assert (ptr_ext == (($past(winner) == N - 1) ? 32'd0 : $past(winner) + 1));
            else
                assert (ptr == $past(ptr));
            cover ($past(rst_n) && ($past(ptr_ext) == N - 1) && (ptr == {PW{1'b0}}));
        end
    end

    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : g_fair
            reg  [31:0] f_wait;
            wire [31:0] f_dist = (g >= ptr_ext) ? (g - ptr_ext) : (g + N - ptr_ext);
            initial f_wait = 32'd0;
            always @(posedge clk) begin
                if (!rst_n || !req[g] || grant[g]) f_wait <= 32'd0;
                else                              f_wait <= f_wait + 32'd1;
            end
            always @(*) begin
                if (f_past_valid) begin
                    assert (f_wait <= N - 1);
                    assert (f_wait + f_dist <= N - 1);
                    if (found && (f_dist < f_dist_win)) assert (!req[g]);
                    cover (rst_n && grant[g]);
                    cover (rst_n && req[g] && grant[g] && (f_wait == N - 1));
                end
            end
        end
    endgenerate
`endif

endmodule
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
`timescale 1ns / 1ps
// ---------------------------------------------------------------------------
// rr_arbiter_tb: self-checking testbench for rr_arbiter (interface_spec.md
// section 6, microarchitecture.md section 5). Two arbiters, N = 4 and N = 5,
// each checked every rising edge against a reference pointer model, with
// per-requester wait counters and coverage goals that fail the run if missed.
// ---------------------------------------------------------------------------

module rr_check #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         init,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    input  wire [N-1:0] grant,
    input  wire         done,
    output reg  [31:0]  passed,
    output reg  [31:0]  failed
);

    localparam [N-1:0] ONEHOT = {{(N-1){1'b0}}, 1'b1};

    // Reference: first requester at or after p, searching (p + d) mod N.
    function [N-1:0] model_grant;
        input [N-1:0] r;
        input integer p_in;
        integer d;
        integer c;
        reg hit;
        begin
            model_grant = {N{1'b0}};
            hit = 1'b0;
            for (d = 0; d < N; d = d + 1) begin
                c = (p_in + d) % N;
                if (!hit && r[c]) begin
                    model_grant[c] = 1'b1;
                    hit = 1'b1;
                end
            end
        end
    endfunction

    function integer winner_of;
        input [N-1:0] gv;
        integer b;
        begin
            winner_of = -1;
            for (b = N - 1; b >= 0; b = b - 1)
                if (gv[b]) winner_of = b;
        end
    endfunction

    integer     p;
    reg         ptr_known;
    reg         seen_run;
    reg         evaluated;
    reg         rot_on;
    integer     rot_k;
    reg [N-1:0] exp_g;
    reg [N-1:0] prev_req;
    reg [N-1:0] mask;
    integer     w [0:N-1];
    integer     cov_alone [0:N-1];
    integer     cov_none;
    integer     cov_all;
    integer     cov_held;
    integer     cov_maxw;
    integer     cov_rst;
    integer     cov_rot;
    integer     i;

    always @(posedge clk) begin
        if (init) begin
            passed    = 0;
            failed    = 0;
            p         = 0;
            ptr_known = 1'b0;
            seen_run  = 1'b0;
            evaluated = 1'b0;
            rot_on    = 1'b0;
            rot_k     = 0;
            prev_req  = {N{1'b0}};
            cov_none  = 0;
            cov_all   = 0;
            cov_held  = 0;
            cov_maxw  = 0;
            cov_rst   = 0;
            cov_rot   = 0;
            for (i = 0; i < N; i = i + 1) begin
                w[i]         = 0;
                cov_alone[i] = 0;
            end
        end

        exp_g = model_grant(req, p);

        if (ptr_known) begin
            // 1. Grant against the reference pointer model.
            if (grant !== exp_g) begin
                $error("rr_check N=%0d: grant %b, expected %b (req %b, model ptr %0d)",
                       N, grant, exp_g, req, p);
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end

            // 2. One-hot or zero, and only to a requester.
            if (((grant & (grant - 1)) != 0) || ((grant & ~req) != 0)) begin
                $error("rr_check N=%0d: grant %b not one-hot-or-zero within req %b",
                       N, grant, req);
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end

            // 3. Work conserving.
            if ((req != 0) && (grant == 0)) begin
                $error("rr_check N=%0d: req %b but no grant", N, req);
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end

            // 4. Strict rotation 0, 1, ..., N-1, 0, ... after reset, all requesting.
            if (rst_n && rot_on && (&req)) begin
                if (grant !== (ONEHOT << (rot_k % N))) begin
                    $error("rr_check N=%0d: rotation step %0d granted %b", N, rot_k, grant);
                    failed = failed + 1;
                end else begin
                    passed = passed + 1;
                end
                rot_k = rot_k + 1;
                if (rot_k == 2 * N) cov_rot = cov_rot + 1;
            end else if (rst_n) begin
                rot_on = 1'b0;
            end

            // 5. Fairness: a held request waits at most N-1 cycles.
            for (i = 0; i < N; i = i + 1) begin
                mask = ~(ONEHOT << i);
                if (rst_n && req[i] && (w[i] > 0) && ((req & mask) != (prev_req & mask)))
                    cov_held = cov_held + 1;
                if (rst_n && (req == (ONEHOT << i)) && (grant == req))
                    cov_alone[i] = cov_alone[i] + 1;
                if (!rst_n) begin
                    w[i] = 0;
                end else if (req[i] && !grant[i]) begin
                    w[i] = w[i] + 1;
                    if (w[i] > N - 1) begin
                        $error("rr_check N=%0d: requester %0d has waited %0d cycles", N, i, w[i]);
                        failed = failed + 1;
                    end else begin
                        passed = passed + 1;
                    end
                end else begin
                    if (req[i] && (w[i] == N - 1)) cov_maxw = cov_maxw + 1;
                    w[i] = 0;
                end
            end

            if (rst_n && (req == 0)) cov_none = cov_none + 1;
            if (rst_n && (&req))     cov_all  = cov_all + 1;
            if (!rst_n && seen_run && (req != 0)) cov_rst = cov_rst + 1;
        end

        // Reference pointer update.
        if (!rst_n) begin
            p         = 0;
            ptr_known = 1'b1;
            rot_on    = 1'b1;
            rot_k     = 0;
        end else if (ptr_known) begin
            seen_run = 1'b1;
            if (exp_g != 0) p = (winner_of(exp_g) + 1) % N;
        end
        prev_req = req;

        // Coverage goals, evaluated once at the end.
        if (done && !evaluated) begin
            evaluated = 1'b1;
            if (cov_none == 0) begin
                $error("rr_check N=%0d: coverage not reached: no requests", N);
                failed = failed + 1;
            end else passed = passed + 1;
            if (cov_all == 0) begin
                $error("rr_check N=%0d: coverage not reached: everyone requesting", N);
                failed = failed + 1;
            end else passed = passed + 1;
            if (cov_held == 0) begin
                $error("rr_check N=%0d: coverage not reached: held request among changing others", N);
                failed = failed + 1;
            end else passed = passed + 1;
            if (cov_maxw == 0) begin
                $error("rr_check N=%0d: coverage not reached: longest fair wait N-1", N);
                failed = failed + 1;
            end else passed = passed + 1;
            if (cov_rst == 0) begin
                $error("rr_check N=%0d: coverage not reached: reset during traffic", N);
                failed = failed + 1;
            end else passed = passed + 1;
            if (cov_rot == 0) begin
                $error("rr_check N=%0d: coverage not reached: two full rotations after reset", N);
                failed = failed + 1;
            end else passed = passed + 1;
            for (i = 0; i < N; i = i + 1) begin
                if (cov_alone[i] == 0) begin
                    $error("rr_check N=%0d: coverage not reached: requester %0d alone", N, i);
                    failed = failed + 1;
                end else passed = passed + 1;
            end
        end
    end

endmodule


module rr_arbiter_tb;

    reg            clk;
    reg            init;
    reg            rst_n;
    reg            done;
    reg  [3:0]     req4;
    reg  [4:0]     req5;
    wire [3:0]     grant4;
    wire [4:0]     grant5;
    wire [31:0]    p4;
    wire [31:0]    f4;
    wire [31:0]    p5;
    wire [31:0]    f5;
    reg  [31:0]    rnd;
    reg  [8*64-1:0] nonce;
    integer        k;
    integer        total_passed;
    integer        total_failed;

    rr_arbiter #(.N(4)) dut4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) dut5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

    rr_check #(.N(4)) chk4 (.clk(clk), .init(init), .rst_n(rst_n), .req(req4),
                            .grant(grant4), .done(done), .passed(p4), .failed(f4));
    rr_check #(.N(5)) chk5 (.clk(clk), .init(init), .rst_n(rst_n), .req(req5),
                            .grant(grant5), .done(done), .passed(p5), .failed(f5));

    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    // Stimulus is applied on falling edges; checks run on rising edges.
    initial begin
        init  = 1'b1;
        rst_n = 1'b0;
        done  = 1'b0;
        req4  = 4'd0;
        req5  = 5'd0;
        rnd   = 32'h1234_5678;
        @(negedge clk);
        init = 1'b0;
        repeat (2) @(negedge clk);
        rst_n = 1'b1;

        // No requests.
        repeat (3) @(negedge clk);

        // Each requester alone.
        for (k = 0; k < 5; k = k + 1) begin
            req4 = 4'b0001 << k;
            req5 = 5'b00001 << k;
            repeat (2) @(negedge clk);
        end
        req4 = 4'd0;
        req5 = 5'd0;
        @(negedge clk);

        // Traffic, reset during traffic, then everyone requesting from reset:
        // strict rotation and the longest fair wait.
        req4 = 4'hF;
        req5 = 5'h1F;
        @(negedge clk);
        rst_n = 1'b0;
        repeat (2) @(negedge clk);
        rst_n = 1'b1;
        repeat (15) @(negedge clk);

        // A held request (requester 2) among changing others.
        for (k = 0; k < 80; k = k + 1) begin
            rnd  = rnd * 32'd1103515245 + 32'd12345;
            req4 = rnd[19:16] | 4'b0100;
            req5 = rnd[28:24] | 5'b00100;
            @(negedge clk);
        end

        // Random subsets with drops and re-raises, and a reset during traffic.
        for (k = 0; k < 600; k = k + 1) begin
            rnd  = rnd * 32'd1103515245 + 32'd12345;
            req4 = rnd[19:16];
            req5 = rnd[28:24];
            if (k == 300) rst_n = 1'b0;
            if (k == 302) rst_n = 1'b1;
            @(negedge clk);
        end

        // Dense burst, then idle.
        req4 = 4'hF;
        req5 = 5'h1F;
        repeat (12) @(negedge clk);
        req4 = 4'd0;
        req5 = 5'd0;
        repeat (2) @(negedge clk);

        done = 1'b1;
        repeat (3) @(negedge clk);

        total_passed = p4 + p5;
        total_failed = f4 + f5;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_passed, total_failed);
        $finish;
    end

endmodule
